<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Interaction Atlas</title><style>body{font:16px system-ui;background:#07131f;color:#eaf2f8;display:grid;place-items:center;min-height:100vh;margin:0}.wrap{width:min(850px,92vw);display:grid;grid-template-columns:1fr 1fr;gap:18px}.card{background:#102334;padding:32px;border-radius:18px;box-shadow:0 24px 70px #0008}input,button{box-sizing:border-box;width:100%;padding:12px;margin:6px 0;border-radius:9px;border:1px solid #315067;background:#081925;color:white}button{background:#31d0aa;color:#041a16;border:0;font-weight:700}small{color:#91a9ba}.error{color:#ff8c91}@media(max-width:700px){.wrap{grid-template-columns:1fr}}</style></head><body><div class="wrap"><form class="card" method="post" action="/login">@csrf<h1>Interaction Atlas</h1><p>Understand your Facebook and Messenger interactions—privately.</p><input type="email" name="email" placeholder="Email" required><input type="password" name="password" placeholder="Password" required><button>Sign in</button></form><form class="card" method="post" action="/register">@csrf<h2>Create an account</h2><input name="name" placeholder="Name" required maxlength="100"><input type="email" name="email" placeholder="Email" required><input type="password" name="password" placeholder="Password · at least 12 characters" required minlength="12"><input type="password" name="password_confirmation" placeholder="Confirm password" required><button>Create account</button><small>Only upload exports from your own account or data you are authorized to analyze.</small></form>@if($errors->any())<div class="card error">{{ $errors->first() }}</div>@endif</div></body></html>
